public class Main {
    static class Team {
        int id, aff, solved, penalty;

        Team(int id, int aff, int solved, int penalty) {
            this.id = id;
            this.aff = aff;
            this.solved = solved;
            this.penalty = penalty;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        StringBuilder out = new StringBuilder();

        while (true) {
            int n = fs.nextInt();
            if (n == 0) break;

            Team[] teams = new Team[n];
            for (int i = 0; i < n; i++) {
                int id = fs.nextInt();
                int aff = fs.nextInt();
                int solved = fs.nextInt();
                int penalty = fs.nextInt();
                teams[i] = new Team(id, aff, solved, penalty);
            }

            Arrays.sort(teams, (a, b) -> {
                if (a.solved != b.solved) return b.solved - a.solved;
                if (a.penalty != b.penalty) return a.penalty - b.penalty;
                return a.id - b.id;
            });

            Map<Integer, Integer> selectedPerAff = new HashMap<>();
            List<Integer> selectedIds = new ArrayList<>();

            for (Team t : teams) {
                int selected = selectedIds.size();
                int cnt = selectedPerAff.getOrDefault(t.aff, 0);
                boolean ok = false;

                if (selected < 10) {
                    if (cnt < 3) ok = true;
                } else if (selected < 20) {
                    if (cnt < 2) ok = true;
                } else if (selected < 26) {
                    if (cnt < 1) ok = true;
                }

                if (ok) {
                    selectedIds.add(t.id);
                    selectedPerAff.put(t.aff, cnt + 1);
                }

                if (selectedIds.size() == 26) break;
            }

            for (int id : selectedIds) {
                out.append(id).append('\n');
            }
        }

        System.out.print(out.toString());
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }
